    "id": "post-6",
    "slug": "how-i-fit-25-plants-in-one-shelf-using-hydroponics",
    "title": "How I Fit 25 Plants in One Shelf Using Hydroponics",
    "date": "April 8, 2026",
    "readTime": "12 min read (2,605 words)",
    "author": "Tehrov",
